import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int n = scanner.nextInt();
        String binaryCode = Integer.toBinaryString(n - 1);
        binaryCode = "0".repeat(h - binaryCode.length()) + binaryCode;
        int accum = 0;
        boolean flipBit = true;
        for (int i = 0; i < h; i++) {
            if (binaryCode.charAt(i) == (flipBit ? '1' : '0')) {
                accum += Math.pow(2, h - i);
            } else {
                flipBit = !flipBit;
                accum += 1;
            }
        }
        System.out.println(accum);
    }
}
